function main(): void {
  const S = Symbol('s');
  let reads = 0;
  let writes = 0;
  let stored = 0;
  const o: any = Object.defineProperties({}, { [S]: { get: () => { reads++; return stored; }, set: (v: number) => { writes++; stored = v; }, enumerable: true, configurable: true } });
  o[S] = 9;
  console.log(o[S], reads, writes, stored);
}
